<template>
  <div class="chat-input">
    <input
      id="chat-input"
      type="text"
      class="type"
      tabindex="-1"
      :value="input"
      @input="onInput"
      @keydown.up="onArrowUp"
      @keydown.down="onArrowDown"
      @keydown.left="onArrowLeft"
      @keydown.right="onArrowRight"
      @keydown.tab="onTab"
      @keyup.enter="$emit('sendMsg')"
    />
    <transition name="slide-fade">
      <div class="autocomplete-wrap" v-show="isOpenAutoComplete">
        <ul class="autocomplete-items">
          <li
            v-for="(result, i) in foundCommands"
            :key="i"
            @click="setInput(`/${result.CommandText}`)"
            class="autocomplete-item"
            :class="{ 'autocomplete-item-active': i === arrowCounter }"
          >
            {{ result.CommandText }}
            <div class="autocomplete-params">
              <div
                class="autocomplete-param"
                v-for="(param, i) in result.Parameters"
                :class="{ 'autocomplete-param-active': i === activeParam }"
                :key="param"
              >
                {{ param }}
              </div>
            </div>
          </li>
        </ul>
      </div>
    </transition>
  </div>
</template>

<script>
export default {
  name: "chat-input",
  emits: [
    "update:input",
    "update:isOpenAutoComplete",
    "sendMsg",
    "historyUp",
    "historyDown",
  ],
  props: {
    input: String,
    foundCommands: Array,
    isOpenAutoComplete: Boolean,
  },
  data() {
    return {
      arrowCounter: 0,
      activeParam: -1,
    };
  },
  methods: {
    onInput(e) {
      const text = e.target.value;
      this.setInput(text);
      this.arrowCounter = 0;

      if (
        this.foundCommands.length < 1 ||
        !this.foundCommands[this.arrowCounter]
      )
        return (this.activeParam = -1);
      this.activeParam =
        text.split(" ").length - 2 >=
        this.foundCommands[this.arrowCounter].Parameters.length
          ? this.foundCommands[this.arrowCounter].Parameters.length - 1
          : text.split(" ").length - 2;
    },
    setInput(text) {
      this.$emit("update:input", text);
    },
    onArrowUp(e) {
      e.preventDefault();
      this.$emit("historyUp");
      // if (this.isOpenAutoComplete && this.foundCommands.length > 1) {
      //   if (this.arrowCounter > 0) {
      //     this.arrowCounter = this.arrowCounter - 1;
      //   } else {
      //     this.arrowCounter = this.foundCommands.length - 1;
      //   }
      // } else {
      //   this.$emit("historyUp");
      // }
    },
    onArrowDown(e) {
      e.preventDefault();
      this.$emit("historyDown");
      // if (this.isOpenAutoComplete && this.foundCommands.length > 1) {
      //   if (this.arrowCounter < this.foundCommands.length - 1) {
      //     this.arrowCounter = this.arrowCounter + 1;
      //   } else {
      //     this.arrowCounter = 0;
      //   }
      // } else {
      //   this.$emit("historyDown");
      // }
    },
    onArrowLeft(e) {
      e.preventDefault();
      if (this.isOpenAutoComplete && this.foundCommands.length > 1) {
        if (this.arrowCounter > 0) {
          this.arrowCounter = this.arrowCounter - 1;
        } else {
          this.arrowCounter = this.foundCommands.length - 1;
        }
      }
    },
    onArrowRight(e) {
      e.preventDefault();
      if (this.isOpenAutoComplete && this.foundCommands.length > 1) {
        if (this.arrowCounter < this.foundCommands.length - 1) {
          this.arrowCounter = this.arrowCounter + 1;
        } else {
          this.arrowCounter = 0;
        }
      }
    },
    onTab(e) {
      e.preventDefault();
      if (!this.isOpenAutoComplete || this.foundCommands[0] === this.type)
        return;
      this.setInput(`/${this.foundCommands[this.arrowCounter].CommandText}`);
      //this.$emit('update:isOpenAutoComplete', false)
      this.arrowCounter = 0;
    },
  },
};
</script>

<style lang="scss" scoped>
.chat-input {
  position: relative;
  width: 100%;
  overflow: visible;
  direction: ltr;

  input {
    width: 100%;
    background: rgba($background, 0.1);
    border: 2px solid rgba(lighten($background, 40%), 0.7);
    padding: 5px 10px;
    font-weight: bold;
    color: rgba($white-text, 0.9);
    border-radius: 0 0 2px 2px;

    &:focus {
      outline: none;
    }
  }
}

.autocomplete-wrap {
  position: absolute;
  margin: 0;
  border-radius: 2px;
  background: rgba($background, 0.4);
  padding: 3px 5px;
  width: 100%;
  top: 38px;
}

.autocomplete-item {
  padding: 5px 10px;
  cursor: pointer;
  color: $white-text;
  border-radius: 2px;
  margin: 2px 0;
  font-weight: bold;
  font-size: 13px;
  display: flex;
  align-items: center;

  .autocomplete-params {
    margin-left: 1px;
    display: flex;

    .autocomplete-param {
      margin: 0 2px;
      background: rgba($foreground, 0.5);
      border-radius: 5px;
      padding: 2px 5px;
      font-size: 12px;
      color: darken($white-text, 15%);
    }
  }
}

.autocomplete-item-active {
  .autocomplete-params {
    .autocomplete-param-active {
      outline: 1px solid $blue;
    }
  }
}

.autocomplete-item-active,
.autocomplete-item:hover {
  background: rgba($background, 0.4);
  color: darken($white-text, 15%);
}
</style>
