<template>
  <div class="tabs">
    <ul class="tabs_header">
      <li class="tab_header" v-for="tab in tabTitles" :key="tab.title" :class="{ selected: tab.title === selectedTitle }" @click="selectedTitle = tab.title">
        <div class="inner">
          {{ tab.title }}
        </div>
      </li>
    </ul>
    <slot />
  </div>
</template>

<script>
import { ref, provide } from "vue";

export default {
  name: "TabsWrapper",
  mounted() {
    document.addEventListener("keyup", this.switchTab);
  },
  methods: {
    findIndex(title) {
      return this.tabTitles.findIndex(function(tab) {
        return tab.title === title;
      });
    },
    switchTab(e) {
      let current = this.findIndex(this.selectedTitle);
      if (e.keyCode === 39) {
        this.selectedTitle = this.tabTitles[current + 1 <= this.tabTitles.length - 1 ? current + 1 : 0].title;
      } else if (e.keyCode === 37) {
        this.selectedTitle = this.tabTitles[current - 1 >= 0 ? current - 1 : this.tabTitles.length - 1].title;
      }
    },
  },
  setup(props, { slots }) {
    const tabTitles = ref(slots.default().map((tab) => tab.props));
    const selectedTitle = ref(tabTitles.value[0].title);

    provide("selectedTitle", selectedTitle);
    return {
      selectedTitle,
      tabTitles,
    };
  },
};
</script>

<style scoped lang="scss">
.tabs {
  font-family: "Nunito", sans-serif;
  font-weight: bold;
  display: flex;
  flex-direction: column;
  height: 100%;
  width: 100%;
}

.bx {
  display: flex;
  justify-content: center;
  align-items: center;
  font-size: 27px;
}

.logo {
  width: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 10px 0px 5px 0px;

  //background: #2d6ae3;

  img {
    width: 50px;
    -webkit-user-drag: none;
  }
}

.tabs_header {
  padding: 5px 5px;
  width: 100%;
  color: $gray-text;
  font-size: 15px;
  background: rgba($score-bg, 0.5);
  display: grid;
  grid-template-columns: auto auto auto;
  grid-gap: 5px;
  align-items: center;
  border-bottom: 1.5px solid rgba(241, 241, 241, 0.7);

  .selected {
    background: rgba(lighten($score-bg, 100%), 0.4) !important;
  }

  .tab_header {
    display: grid;
    justify-content: center;
    align-items: center;
    cursor: pointer;

    background: rgba(lighten($score-bg, 50%), 0.4);
    padding: 2px 5px;
    border-radius: 2px;
    color: rgba(lighten($score-bg, 80%), 0.7);
    transition: background 0.4s;
  }
}
</style>
