<template>
  <div class="panel">
    <span class="text">{{ title }}</span><span class="time"><i class="fa-solid fa-stopwatch"></i>{{ formatted }}</span>
  </div>
</template>

<script>
export default {
  name: "GameProgress",
  data() {
    return {
      title: "Time Left",
      time: 0
    }
  },
  methods: {
    format(time) {
      var mins = ~~((time % 3600) / 60);
      var secs = ~~time % 60;
      var ret = "";
      ret += "" + mins + ":" + (secs < 10 ? "0" : "");
      ret += "" + secs;
      return ret;
    }
  },
  computed: {
    formatted() {
      return this.format(this.time);
    }
  }
}
</script>


<style scoped lang="scss">
.panel {
  float: right;
  height: 35px;
  padding: 5px 20px 5px 45px;
  border-radius: 10px;
  display: flex;
  justify-content: center;
  align-items: center;
  color: rgba($white-text, 0.8);
  font-family: 'Nunito', sans-serif;
  font-weight: bold;
  font-size: 15px;
  background: rgba($background, 0.4);
  min-width: 250px;
  margin-top: 5px;

  .text {
    margin-right: 50px;
  }

  .time {
    float: right;
    display: flex;
    justify-content: center;
    align-items: center;
  }

  i {
    font-size: 20px;
    margin-right: 8px;
  }
}
</style>