<template>
  <div class="fuel">
    <div
      class="fuel-inner"
      :style="{
        background: `linear-gradient(0deg, ${fillColor} ${tweenedFuel}%, rgba(0, 212, 255, 0) ${
          tweenedFuel + 20
        }%)`,
      }"
    >
      <i :class="fuelIcon" style="--fa-animation-duration: 0.6s; --fa-beat-scale: 1.1"></i>
    </div>
  </div>
</template>

<script>
import gsap from "gsap";

export default {
  props: ["fugitive"],
  data() {
    return {
      fuelIcon: "fa-solid fa-gas-pump",
      fuel: 15,
      tweenedFuel: 15,
      copColor: "rgb(91, 145, 254, 0.8)",
      fugitiveColor: "rgb(255, 149, 0, 0.8)",
      warningColor: "rgb(139, 55, 213, 0.8)",
      fillColor: "rgb(255, 149, 0, 0.8)",
      fWarningId: null,
      fuelMinWarning: 15,
    };
  },
  mounted() {
    setInterval(() => {
      if (this.fuel <= 0) return (this.fuel = 100);

      if (!this.fWarningId && this.fuel <= this.fuelMinWarning)
        this.fWarningId = setInterval(() => {
          if (this.fillColor === (this.fugitive ? this.fugitiveColor : this.copColor)) {
            this.fillColor = this.warningColor;
            if (this.fuelIcon !== "fa-solid fa-gas-pump fa-beat")
              this.fuelIcon = "fa-solid fa-gas-pump fa-beat";
          } else {
            this.fillColor = this.fugitive ? this.fugitiveColor : this.copColor;
          }
        }, 800);

      if (this.fWarningId && this.fuel > this.fuelMinWarning)
        clearInterval(this.fWarningId),
          (this.fWarningId = null),
          (this.fuelIcon = "fa-solid fa-gas-pump");

      //this.fuel--;
    }, 1000);
  },
  watch: {
    fuel(newValue) {
      gsap.to(this.$data, { duration: 0.5, tweenedFuel: newValue });
    },
  },
};
</script>

<style lang="scss" scoped>
.jurac {
  color: rgb(139, 55, 213);
}

.fuel {
  border-radius: 100%;
  height: 50px;
  width: 50px;
  position: absolute;
  top: -90px;
  right: 80px;
  display: flex;
  justify-content: center;
  align-items: center;
  background: rgba(0, 0, 0, 0.2);

  .fuel-inner {
    border-radius: 100%;
    display: flex;
    justify-content: center;
    align-items: center;
    width: 100%;
    height: 100%;
  }

  .fa-solid {
    font-size: 20px;
    color: $white-text;
  }
}
</style>
