<template>
  <button
    @click="fortnite"
    style="height: 500px; width: 500px; border-radius: 100%; background: orange; font-size: 50px"
  >
    AGARIO <span v-if="seksniga > 0" style="font-size: 250px">👩🏿‍🌾</span
    ><img v-else src="https://i.gifer.com/7TnS.gif" alt="" />
    {{ seksniga }}
  </button>
  <div v-show="hud">
    <TopRight
      v-if="topRight"
      :stats="stats"
      :toolTips="toolTips"
      :gameProgress="gameProgress"
      :killFeed="killFeed"
      :topRightInfo="topRightInfo"
      ref="TopRight"
    />
    <BottomRight
      :fugitive="stats.fugitive"
      :fuelStatus="fuelStatus"
      :speedo="speedo"
      ref="BottomRight"
    />

    <MiniHud v-if="miniHud" ref="MiniHud" />

    <transition name="fade" appear>
      <Scoreboard v-show="scoreboard" :stats="stats" ref="scoreboard" />
    </transition>

    <transition name="fade" appear>
      <ActionBar v-show="actionBar" :fugitive="stats.fugitive" ref="actionbar" />
    </transition>

    <chat v-show="chat" :devMode="devMode" ref="chat" />
  </div>
</template>

<script>
import { ref } from "vue";
import seks from "./assets/seks.ogg";
import { useSound } from "@vueuse/sound";
import TopRight from "./components/TopRight/TopRight";
import Scoreboard from "./components/General/Scoreboard/Scoreboard";
import ActionBar from "./components/General/ActionBar";
import MiniHud from "./components/MiniHud/MiniHud";
import BottomRight from "./components/BottomRight/BottomRight";
import Chat from "./components/Chat/Chat";

export default {
  name: "App",
  components: {
    Chat,
    TopRight,
    Scoreboard,
    ActionBar,
    MiniHud,
    BottomRight,
  },
  data() {
    return {
      stats: {
        squad: -1,
        lobby: 2,
        admin: 2,
        fugitive: false,
      },

      //Hud
      hud: true,
      gameProgress: true,
      killFeed: true,
      topRightInfo: true,
      topRight: true,
      scoreboard: false,
      miniHud: true,
      chat: true,

      devMode: false,
      seksniga: 25,

      //General
      actionBar: false,
      toolTips: true,
      speedo: false,
      fuelStatus: false,
    };
  },
  setup() {
    const playbackRate = ref(1.5);

    const { play } = useSound(seks, {
      playbackRate,
      interrupt: true,
    });

    const fortnite = () => {
      playbackRate.value = playbackRate.value + 0.1;

      play();
    };

    return {
      fortnite,
    };
  },
  methods: {
    sendAch(title, description, url, reward = false, time = 5000) {
      global.iziToast.show({
        id: "achv-toast",
        class: "achv-toast",
        image: url,
        title: title,
        message: `${description}${reward && `<br><br><b>${reward}</b>`}`,
        timeout: time,
        progressBarColor: "rgba(0, 195, 255, 0.8)",
      });
    },
  },
  mounted() {
    let dev = process.env.NODE_ENV === "development" ? true : false;

    this.devMode = dev;
    this.stats.admin = dev ? 1 : 0;

    setInterval(() => {
      if (!isNaN(this.seksniga) && this.seksniga > 0) this.seksniga--;
      else this.seksniga = "💩";
      if (this.seksniga === 0) this.fortnite();
    }, 1000);
    console.log("seks");
    this.fortnite();
    global.Swal.fire("نيغا نيغا", "نيغا نيغا", "warning");
  },
};
</script>

