<template>
  <div class="msg">
    <div :id="timestamp">
    </div>
  </div>
</template>

<script>
import $ from "jquery";

export default {
  name: "chat-message",
  props: {
    message: {
      type: String,
      required: true
    }
  },
  data() {
    return {
      timestamp: Date.now()
    }
  },
  methods: {
    escapeHtml(unsafe) {
      return unsafe.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;').replaceAll('"', '&quot;').replaceAll("'", '&#039;');
    }
  },
  mounted() {
    let chat = $(`#${this.timestamp}`);

    let colorPositions = [];
    let colors = [];
    let chatElement = "<div>";
    let text = "!{#FFFFFF}" + this.escapeHtml(this.message);
    for (let i = 0; i < text.length; i++
    ) {
      let colorCheck = `${text[i]}${text[i + 1]}${text[i + 2]}`;

      if (colorCheck === "!{#" || (text[i] === "~" && text[i + 2] === "~")) {
        colorPositions.push(i);
      }
    }

    colorPositions.forEach(el => {
      let sub = text.slice(el, -1);
      if (sub[0] === "~") {
        colors.push(sub.slice(0, 3));
      } else {
        colors.push(sub.slice(3, 9));
      }
    });

    function getColor(char) {
      switch (char) {
        case "r":
          return "red"
        case "b":
          return "blue"
        case "g":
          return "green"
        case "y":
          return "yellow"
        case "q":
          return "purple"
        case "p":
          return "pink"
        case "o":
          return "pink"
        case "w":
          return "white"
      }
    }

    colorPositions.forEach((el, i) => {
      let sub = text.slice(colorPositions[i] + 10, colorPositions[i + 1]);
      let sub2 = text.slice(colorPositions[i] + 3, colorPositions[i + 1]);
      let charCheck = colors[i].split('')[0] === "~";
      chatElement += `<span style='color: ${charCheck ? getColor(colors[i].split('')[1]) : "#" + colors[i]}'>${charCheck ? sub2 : sub}</span>`;
    });

    chatElement += "</div>";

    if (chatElement === "<div></div>") {
      chat.prepend("<div>" + text + "</div>");
    } else {
      chat.prepend(chatElement);
    }
  }
}
</script>

<style lang="scss" scoped>
.msg {
  word-break: break-all;

  .timestamp {
    margin-right: 5px;
    color: $white-text;
    font-weight: bold;
    min-width: max-content;
  }

  .author {
    margin-right: 5px;
    min-width: max-content;
    font-weight: bold;
  }
  li {
    list-style: none;
  }
}
</style>